import 'dart:io';import 'dart:convert';import 'package:flutter/material.dart';import 'package:flutter/services.dart';import 'package:flutter_test/flutter_test.dart';import 'package:shared_preferences/shared_preferences.dart';import '../lib/features/mushaf/screens/quran_asbab_nuzul_screen.dart';
void main(){for(final edition in ['lubab']){for(final width in [480.0]){testWidgets('unmapped verse stays unavailable while opt-in chapter context opens offline',(t)async{
TestDefaultBinaryMessengerBinding.instance.defaultBinaryMessenger.setMockMessageHandler('flutter/assets',(m)async{final p=utf8.decode(m!.buffer.asUint8List());final f=File(p);return f.existsSync()?ByteData.sublistView(f.readAsBytesSync()):null;});
SharedPreferences.setMockInitialValues({'default_tafsir_edition':edition});
t.view.physicalSize=Size(width,1100);t.view.devicePixelRatio=1;addTearDown(t.view.resetPhysicalSize);addTearDown(t.view.resetDevicePixelRatio);
final key=GlobalKey();
await t.pumpWidget(RepaintBoundary(key:key,child:MaterialApp(debugShowCheckedModeBanner:false,theme:ThemeData(fontFamily:'Amiri'),home:Directionality(textDirection:TextDirection.rtl,child:Scaffold(body:const QuranAsbabNuzulScreen(initialSurahId:94,initialAyah:1))))));
await t.runAsync(()async{for(var i=0;i<100;i++){await Future<void>.delayed(const Duration(milliseconds:20));await t.pump();if(find.textContaining('لا يوجد حاليا نص مرتبط بهذه الآية من لباب النقول').evaluate().isNotEmpty)break;}});await t.pumpAndSettle();expect(find.textContaining('لا يوجد حاليا نص مرتبط بهذه الآية من لباب النقول'),findsOneWidget);
await t.ensureVisible(find.text('سياق السورة في الكتاب'));await t.tap(find.text('سياق السورة في الكتاب'));await t.pump();await t.runAsync(()async{for(var i=0;i<100;i++){await Future<void>.delayed(const Duration(milliseconds:20));await t.pump();if(find.textContaining('هذا نص فصل السورة').evaluate().isNotEmpty)break;}});await t.pumpAndSettle();expect(find.textContaining('هذا نص فصل السورة'),findsOneWidget);await t.ensureVisible(find.textContaining('هذا نص فصل السورة'));await t.pumpAndSettle();await t.ensureVisible(find.text('مقدمة الكتاب'));await t.tap(find.text('مقدمة الكتاب'));await t.pump();await t.runAsync(()async{for(var i=0;i<100;i++){await Future<void>.delayed(const Duration(milliseconds:20));await t.pump();if(find.textContaining('مقدمة لباب النقول وتنبيهات').evaluate().isNotEmpty)break;}});await t.pumpAndSettle();expect(find.textContaining('مقدمة لباب النقول وتنبيهات'),findsOneWidget);expect(t.takeException(),isNull);
});}}
}